) AS (
  VALUES 
    (665::BIGINT, 'El curso es sencillo, los trabajos que deja el profesor ayudan a comprender en gran manera los contenidos. Lo ideal es tener un buen grupo de trabajo, el curso es prácticamente grupal.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Deja trabajos largos']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd57f2b93757cc61436cf32355e2ee851d449f2c885ef3055bee1a41183df9b65'::TEXT, ARRAY[2530]::BIGINT[]),
    (665::BIGINT, 'Profe 10/10, de mis favoritos, es bien chistoso. Todos los trabajos son grupales , se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'bfb14e2f88c3629a772fb51b9a1d49c5ea75d066acdedbd5297029d397d63422'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'El GOAT Si no lo pasa, preocúpese'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, '0e356cd9b7271777ad2f380eb08cdce17725bf7cd79abca0ad5f5c2465994fb7'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Deja muchos trabajos en grupo, así que sugiero escoger un grupo dispuesto a trabajar. El curso se pasa solo si entrega todo y hace los exámenes, que suelen ser virtuales. Eso sí, olvídese de saber su nota, porque la da hasta el último momento.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '90cc344bca7a57c8e471ed9f4b44c88cd2c59661d35bee957aed174415ebf60f'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'En general el profe es bueno explicando la materia y califica muy suave, uno no siente que lleva el curso hasta las últimas dos semanas. Sin embargo, uno no sabe ninguna nota a excepción de examenes hasta la última semana, básicamente se va a ciegas en calificación todo el curso.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b562ea5c56780643dbc6cba8d0d83362c420b1471a6c7af4e7aaa9af40af93c8'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '02d8ac2870bc95776fc1aadbb284c21188ce6fb2ef6fdd9e35460b38dfd59f2a'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'El curso súper llevadero, la parte de presupuesto es lo que hay que dedicarle más tiempo, pero con hacer las tareas se pasa muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, '24fd40a2f11040274a08d91383fb9e164d27ed43490e1610dcf630a67d56ae22'::TEXT, ARRAY[2529]::BIGINT[]),
    (665::BIGINT, 'Curso super fácil y uno ni se da cuenta que lo lleva hasta como las últimas 2 semanas.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2023-07-10T00:00:00+00:00'::TIMESTAMPTZ, '0b512949e33a6db6ed8fca83b798cb23441fa465c1b21ec0bcb48ca682193a37'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'El curso se pasa muy sencillo. Se hacen 2 trabajos en grupo muy fáciles. Hace exámenes virtuales muy fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '651566164050792a76ecae7c22048df260230f87b7a35d7fd6bcf02a42f38e3b'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'El curso se pasa solo. Básicamente, haciendo los trabajos, da igual qué tan bien o mal estén vas a sacar 80 o más en la nota. Suele exámenes virtuales.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '4cc4f218aaad772b866251c4462ea5df41f26834a044481094ce347037ea1c78'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Es súper fácil pasar el curso con él. Prácticamente todo se hace en grupos y es sumamente fácil ya que no califica duro. Los exámenes individuales son súper sencillos y el profe es agradable.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'bdf09d501faf359522910642f09b64c8ec065c948e0e751f1386fc3289b4ba96'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'El curso prácticamente es autodidacta y en su mayoría grupal. Son 2 exámenes, casos y proyecto. Lo único individual es un curso online de Cisco sobre emprendimiento. El profe es desentendido, prácticamente deja solo videos y nada que contesta correos. Ud se da cuenta de sus notas hasta el final'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '999832fbb28f8be46d864c0c4f9d21e903bd471ad7dc876434b7477a1d1a0ac6'::TEXT, ARRAY[2580]::BIGINT[]),
    (665::BIGINT, 'No sé el curso es fácill, las instrucciones muy ambiguas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ca5e48ebebb49b8fca53294855b3e8b33713bffc6a05908113a7bd73a8b039b1'::TEXT, ARRAY[2580]::BIGINT[]),
    (665::BIGINT, 'El curso se pasa solo, se enreda al explicar pero la idea de la clase se retoma fácilmente, haga todos los trabajos, acate instrucciones y saca buena nota.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'd5e7afd10360c9cfd43b2903f9746e12d8603a430fcde77da17aa6ba5efa8555'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'El curso se pasa solo si usted hace las cosas, el problema es que cuando explica se va siempre por las ramas haciendo que uno se confunda y si te desconcentras 10 segundos, a veces no pasa las presentaciones ojo ahí , muy buena nota el profe en general'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e5abc92452d0757ccaf31e3030477ba068e9c8b2358198ab17e60b4fac1303c0'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Un muy buen profe la verdad, si da mucha materia pero igual se pasa super facil'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '360d55c64c7e58de419118d51fd85e81137ce15431f8442d16e58c7816c65a95'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Me gusta la forma en la que explica, la materia es interesante, pero a veces me llegaba a perder, en lo que son recomendaciones para proyectos o tareas , él daba muy buenos consejos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '3630a15bc89c5d9a5663e3dac1a94cd61dbac8e1dd4c3477d14794c9f39ef926'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Las clases con el profe son extensas, sin embargo muchos reciben el curso de manera asincronica, los trabajos a veces son sencillos, pero son muy largos, leer mucho, investigar mucho, pero los cursos con el son faciles de pasar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '314545b45e44c62470c8807ec2b5b82e6d6fa1e9c469e7a84ed69c34ff7fba72'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Es DEMASIADO aburrido, en el segundo grupo lo que hace es poner una grabación y si mete a las 7:30 se va a quedar dormido, pero eso sí, es muy fácil, aunque no sabe si pasó hasta el final porque no da notas'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'debf4a677da71b92ab5d71cd1ecd62536feb922f8022c8aa27f927796584c3fd'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'El profe sí es bastante vago, si usted está en el segundo grupo lo que va a hacer es mostrarle la grabación del primer grupo, así que es bastante aburrido. De igual forma, el curso es muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'd690e2360d7bf1e7204ebe0775e21cb9d02e166e053fefdff0f71460e183dc5c'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Es muy desordenado. Es todo vago. Graba las clases y las solo comparte pantalla con esa grabación. Las clases son súper aburridas, solo es esa grabación. Igual el tema es fácil, es algo lógico. El curso es fácil. Cuesta mucho que responda correos y así.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, 'bb4713d0a2d0d4602a85e1625c6d30d4d4ffd926238e98b62f519765851e1927'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'El profe es demasiado desorganizado, llegue a final de semestre sin saber cuanto ma había sacado en tareas, examenes y presentaciones. Falta claridad en las instrucciones.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '16891322e7cbdfc99d4037cb8c5aeae085c6c4657aac975b0d9e96498e6766d3'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'El profe era muy buena en la presencialidad, sin embargo, en las clases virtuales las clases se sentían muy aburridas y simples. Personalmente, perdió ese toque que provocaba querer ir a su clase con la llegada de la virtualidad. De igual manera, no es mal profe, solo no es tan bueno como antes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '344f37ba2e17d8cbc308bc821df0b68862d696e0e9ea42b36471d455365da8e6'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Desde la virtualidad: un vago,graba las clases para no volver a explicar la materia.No sube notas al tec digital y los exámenes son en socrative.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '832d67e5ee9718e3ad5c1c11e544d1cb8a54ef892e160aab59df349c759df949'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Es un buen profe, sin embargo con la virtualización se desintereso por completo. Las clases con el son MUY faciles, casi que para quedarse hay que querer quedarse. Lo recomiendo mucho. Hace solo 3 examenes y 1 proyecto, entonces si no le va bien en eso casi que se quedo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '1fa635dedf44b3f59e361c9b45945d732a12070c4cff466fc1f91466976174ef'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'ad5f7c3f3fc864fc6479335573b36e230914b4f0db0064767aca5b4496c39e4e'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'En cuanto a la clase muchas veces aborda únicamente desde ejemplos lo cual dificulta a la hora de realizar las evaluaciones que requieren de lo práctico, es muy fácil pasar, solo lleve el curso al día. Es muy accesible'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'a4d768f221c1278e7874c6eb736e0abb8da8e1bec45fa121aa7664b0acfee456'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Era buena gente al dar clases pero cuando se virtualizó el curso cambió por completo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '0b8b23d30b4a0faf95408d961eb9bbc5a57e49b8c8106f946f4d8d15f03912f3'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Fue buen profe hasta que se virtualizó el curso. Se hizo muy desordenado y desinteresado'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '7773c1e3caf4258fdd62f4c3bef85d23930ff834cc8815cf709db26508c90740'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'En el curso virtual fue un poco desordenado. Pero estuvo fácil el curso'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'c25ad3605f664302e5a46ca27381c0ed974cc2885a076ab03c7e030d341aff5d'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '58a47da8203ebe8149d815b2e4fe3af7233d89722a414ca6abe312dd3e046645'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Muy buen profe. Clases súper interesantes, se aprende bastante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '0f0157625fdaf791b98513cb16e4d77040d397b535ccb88a118d8953ec3df5a0'::TEXT, ARRAY[2508]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Pocos exámenes']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '9d8b0c97e33abef3b5904f3273ec887afc1fbcc2ee19489d0377e072fceac4f8'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Excelente profe y persona! Ayuda mucho, el curso es suave y aunque los exámenes son engañosos si estudia pasa de lo más bien!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-10-09T00:00:00+00:00'::TIMESTAMPTZ, '969e543e3f90f17859df4068922f1427605f434f9271511e8a1d8ab94f70fb84'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Es una excelente persona, las clases son muy entretenidas y si se estudia bien para los exámenes (que pueden ser un poco engañosos) se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '38a901bde6bfab5a02499b79a007052dec2c1b07708881cd8a31db665ac12f05'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Explica muy bien, los exámenes son un poco difíciles, también mete en los exámenes cosas que no viene en el libro sino cosas que explica en clase. El proyecto es bastante sencillo, pero sube las presentaciones y los archivos en la madrugada y el mismo día de los exámenes y entrega de trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3b08967d8f313b1da96f0b6b10b3a5d5db044e29e56581bb0a21e3b90a5ef0e1'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Super buen profe, las clases son muy interesantes y aunque los exámenes tienen buen nivel si uno estudia le va bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'bb5e75337b451e2d4fbd1bc82def6bae2400264d4ca41a551afbbd5aa4b2e156'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Clases muy entretenidas, exámenes fáciles, si puso atención en clase ya tiene medio examen ganado, su forma de dar la clase es perfecta, despierta el interés del estudiante evitando que se vuelva aburrida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'e9df9eda3c2222dc6437c612057ed0acd4b2317918215fde0634872214abf91f'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Profe muy bueno! Clases muy entretenidas y aunque lee diapositivas las explica! El proyecto y los exámenes son fáciles!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-10T00:00:00+00:00'::TIMESTAMPTZ, '18aeeb926bc3fd0ef869f3599c7b2a854b8fe57a7412f83558988b5d9ee6e27c'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Excelente profe y persona, las clases pueden ser un poco aburridas pero se aprende. Los examenes y el proyecto son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '7ddf89ba6958cf1504d657b569737231e489176bfc84cf1e4dc59798110500ef'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Buen profe y es muy experto en el tema. A veces las clases aburre pero se aprende y explica las diapositivas. Si hace las guías de libro, tres exámenes buenos y entrega el trabajo final pasa. Esa materia es pasable.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c1933ef1a92781fe0ea1fad02502f5c39605eb1f75b0f8b9b4a6b28ee02921f1'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-03-28T00:00:00+00:00'::TIMESTAMPTZ, 'f791648b43d439222a5203c233594649009b9a27e6d7dd0a3fbea7eb2273184d'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Excelente, siempre da ejemplos relacionados con su experiencia y es evidente que es un experto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'b2d6c083e3a366245c3c101ce5435c5427de7093f419da71a23796afde1e7bd1'::TEXT, ARRAY[2580]::BIGINT[]),
    (665::BIGINT, 'Experto en el tema, explica super bien usando ejemplos y anécdotas interesantes. La clase es muy llevadera porque hace bromas para que los estudiantes no se aburran pero tampoco es un charlatán. A veces califica un poco duro si uno no pone exactamente lo que el quiere pero en general el curso es fác'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '889925f420f3101e235b453949059d315fd6ede0fe8fc8aa971fbabe76942444'::TEXT, ARRAY[2515]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'dbc1b98bd792c3cf7a0d64ca6333b45ea964b3e8ced768f0b7f5062335e0d171'::TEXT, ARRAY[1514]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2016-04-30T00:00:00+00:00'::TIMESTAMPTZ, 'c648fe15ebf41fbdf38ad44474b92edda7f030a12a4cb5081fe8bdce61690ccf'::TEXT, ARRAY[2568]::BIGINT[]),
    (665::BIGINT, 'El profe es super bueno, hace muchos chistes bueno y es un experto en su materia y sabe como hacer que las clases sean dinámicas y entretenidas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, '3c7d928440a13c2ce32acf354169f75665acaa67022e853113d3a69d239e2bca'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'fe31b5bf4ca15a4fd7201207a54887d60b52937e1960d7bc99dc76cc3f9c58ef'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Excelente profe! Sus clases pueden ser un poco aburridas pero explica muy bien, sabe bastante. Deja muy pocos trabajos y los que hace son muy fáciles. Para los exámenes si hay que estudiar mucha teoría, pero sencillos. Siempre está ahi para ayudar. Un profe muy simpático, recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '161a93156dbb8db7cc056a5981f337916ef91e4ffa7eb2e5117f2bd61e412422'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Es un excelente profesor! Sus clases son muy buenas y divertidas, siempre tiene empatía con el grupo! Sus clases se basan en ejemplos para entender los temas por lo que debes estudiar bastante la materia xq es teórico y muy puntual! pero a mi parecer ayuda muchiísimo en exámenes! :)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '85ea6105c2f34c7fef5771020d9a31aa56ec481c28134f2270ca21a0e8937684'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Los exámenes son sumamente teóricos, y en la clase prácticamente no hay empatia con el grupo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c53f0cc2c42cc304cd8f2e0c84ad1a8d9c3ed848c442953167d5641cc2f35536'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'aab6c202b0ad6013d537fbc705ab96f8a783646c4bc98961ab6c1ca8a066db0d'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'es un profesor que tiene mucha vocación sabe como llegarle a los estudiantes, los exámenes tienen su nivel, pero si se estudia no hay problema se pasa el curso de manera fácil'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-06T00:00:00+00:00'::TIMESTAMPTZ, '34807b13e12f1e74cbf441279dd3808a8cbe872dfb6b7a258eacfdac44a6d851'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Es un excelente profesor, se aprende con el y te enseña con ejemplos de la vida real, no se apega al libro y es muy buena gente, nada mas que es un poco desorganizado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '1feb7ae245f073e43a72de2b2105be247e3e1fd40c9f92e642e4e0e49a235aa5'::TEXT, ARRAY[2509]::BIGINT[]),
    (665::BIGINT, 'Califica sin rubros, nunca desglosa notas y es injusto para calificar. No explica tanto ni tan bien aunque él si sabe del tema. No es tan ordenado pero si es buena gente. Debería ser mas exigente. Hay mejores profes.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-06T00:00:00+00:00'::TIMESTAMPTZ, '6a1fd8e32f2a4e548f840d1c190ac03969b9c95e4f8c4cf48ac3746c4541c758'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, 'Bueno profe, no es super facil pero tampoco es rudo, es muy buena nota'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'f4d90ff710cc32136f33326a7c00790bd496cdc1eb7c59a1cc14fbadb52e221d'::TEXT, ARRAY[2514]::BIGINT[]),
    (665::BIGINT, '100% recomendado, es fácil, se aprende, las clases son interesantes, excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'a4a5e32308b4306e7304a3e0502350190cf557e619f459ae63e6fefa6ee50116'::TEXT, ARRAY[2514]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
